// RBAC + comprobación de propiedad
function puedeEditar(usuario, producto) {
  if (usuario.rol === 'admin') return true;
  return usuario.rol === 'vendedor' && producto.vendedorId === usuario.id;
}

// ABAC: política con atributos
const politica = {
  accion: 'editar',
  recurso: 'producto',
  condicion: (u, r, ctx) =>
    (u.rol === 'admin') ||
    (u.rol === 'vendedor' && r.vendedorId === u.id && r.estado !== 'en_pedido')
};
